def investigate(context, acquire):
    receipts = context.get('receipts') or []
    seen = set()
    for row in receipts:
        query = row.get('query') if isinstance(row, dict) else None
        if isinstance(query, dict):
            seen.add(repr(query.get('events')))
    for example in context.get('examples') or []:
        if isinstance(example, dict) and isinstance(example.get('input'), dict):
            seen.add(repr(example['input'].get('events')))
    candidates = [
        [{'op':'feed','bytes':[224,128]},{'op':'finish'}],
        [{'op':'feed','bytes':[224,160]},{'op':'finish'}],
        [{'op':'feed','bytes':[240,143]},{'op':'finish'}],
        [{'op':'feed','bytes':[240,144]},{'op':'finish'}],
        [{'op':'feed','bytes':[244,143]},{'op':'finish'}],
        [{'op':'feed','bytes':[244,144]},{'op':'finish'}],
        [{'op':'feed','bytes':[237,159]},{'op':'finish'}],
        [{'op':'feed','bytes':[237,160]},{'op':'finish'}]
    ]
    for events in candidates:
        if repr(events) not in seen:
            return {'query': {'events': events}, 'note': {'hypothesis': 'Parent uses a single low/high pair for all continuation bytes, so it mishandles 3- and 4-byte UTF-8 boundary sequences such as E0 A0, F0 8F, F4 8F, and ED 9F.'}}
    return {'query': None, 'note': {'hypothesis': 'No unused discriminating candidate remained.'}}

