                    if lead < 244:
                        high = 191
                    elif lead == 244:
                        high = 143
                    else:
                        low = 128
                        high = 191
                else:
                    status = 'error'
                    break
                if index + needed >= total:
                    pending = data[index:]
                    index = total
                    break
                valid = True
                position = index + 1
                step = 0
                while step < needed:
                    byte = data[position]
                    if byte < low or byte > high:
                        valid = False
                    position += 1
                    step += 1
                    low = 128
                    high = 191
                if not valid:
                    status = 'error'
                    break
                count += 1
                index = position
            if status == 'error':
                pending = []
        elif op == 'finish':
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}

